{"command":"$ErrorActionPreference = 'Stop'
$repo='edburns/dd-3061974-03-cargotracker-windows'; $branch='copilot/experimentshepherd-control44-implement-primefaces'; $pr=10
$runsRaw = gh run list -R $repo --branch $branch --limit 100 --json databaseId,conclusion,status,headSha,name,url
$listExit = $LASTEXITCODE
if ($listExit -ne 0) { throw "SHEPHERD FAILED: workflow listing exited $listExit" }
$runs = $runsRaw | ConvertFrom-Json
$pending = @($runs | Where-Object conclusion -eq 'action_required')
foreach ($run in $pending) {
  $ok=$false
  for ($attempt=1; $attempt -le 3 -and -not $ok; $attempt++) {
    gh run rerun $run.databaseId -R $repo
    $rerunExit=$LASTEXITCODE
    if ($rerunExit -eq 0) { $ok=$true } elseif ($attempt -lt 3) { Start-Sleep -Seconds 10 }
  }
  if (-not $ok) { throw "SHEPHERD FAILED: unable to rerun workflow $($run.databaseId)" }
}
gh pr checks $pr -R $repo --watch --fail-fast
$checksExit=$LASTEXITCODE
Write-Output "GH_PR_CHECKS_EXIT=$checksExit"
exit 0","description":"Approve and watch PR checks","initial_wait":600,"mode":"sync"}

